INSERT INTO articles (article_id, company_id, title, body, category_id, author_id, reviewed_by, status, view_count, helpful_count, not_helpful_count, published_at, created_at, updated_at) VALUES (1, 1, 'How to reset your password', 'Step-by-step guide to resetting your Northstar Holdings account password via the self-service portal. Navigate to the login page, click ''Forgot Password'' and follow the email instructions.', 5, 11, 2, 'PUBLISHED', 342, 89, 7, '2026-02-01 08:00:00+00', '2026-01-25 08:00:00+00', '2026-02-01 08:00:00+00');
INSERT INTO articles (article_id, company_id, title, body, category_id, author_id, reviewed_by, status, view_count, helpful_count, not_helpful_count, published_at, created_at, updated_at) VALUES (2, 1, 'VPN setup on Windows 11', 'Detailed instructions for configuring the company VPN client on Windows 11. Download the VPN installer from the IT portal, run the installer with administrator rights and use your domain credentials.', 6, 12, 3, 'PUBLISHED', 215, 67, 12, '2026-02-15 08:00:00+00', '2026-02-10 08:00:00+00', '2026-02-15 08:00:00+00');
INSERT INTO articles (article_id, company_id, title, body, category_id, author_id, reviewed_by, status, view_count, helpful_count, not_helpful_count, published_at, created_at, updated_at) VALUES (3, 1, 'Requesting a new laptop', 'How to submit a laptop request through the ESM Hub service catalogue. Log in, navigate to Service Catalogue > Laptop & Desktop and complete the request form with your manager approval.', 2, 11, 2, 'PUBLISHED', 180, 55, 5, '2026-03-01 08:00:00+00', '2026-02-25 08:00:00+00', '2026-03-01 08:00:00+00');
INSERT INTO articles (article_id, company_id, title, body, category_id, author_id, reviewed_by, status, view_count, helpful_count, not_helpful_count, published_at, created_at, updated_at) VALUES (4, 1, 'Connecting to the office Wi-Fi', 'Guide to connecting to Northstar Wi-Fi networks. Use network name NORTHSTAR-CORP and authenticate with your Active Directory credentials. Contact the helpdesk if you need a guest network token.', 3, 13, 4, 'PUBLISHED', 128, 41, 3, '2026-03-10 08:00:00+00', '2026-03-05 08:00:00+00', '2026-03-10 08:00:00+00');
INSERT INTO articles (article_id, company_id, title, body, category_id, author_id, reviewed_by, status, view_count, helpful_count, not_helpful_count, published_at, created_at, updated_at) VALUES (5, 1, 'ERP system login troubleshooting', 'Common fixes for Business ERP login issues including account lockout, browser compatibility and session timeout. If locked out wait 15 minutes or contact the Service Desk.', 4, 14, 2, 'PUBLISHED', 97, 30, 8, '2026-04-01 08:00:00+00', '2026-03-28 08:00:00+00', '2026-04-01 08:00:00+00');
INSERT INTO articles (article_id, company_id, title, body, category_id, author_id, reviewed_by, status, view_count, helpful_count, not_helpful_count, published_at, created_at, updated_at) VALUES (6, 1, 'Printer setup and troubleshooting', 'How to add a network printer and resolve common printing errors. Open Settings > Printers & Scanners, select Add Printer and choose the printer by IP. Restart the print spooler if jobs are stuck.', 7, 11, 3, 'PUBLISHED', 156, 48, 10, '2026-04-15 08:00:00+00', '2026-04-10 08:00:00+00', '2026-04-15 08:00:00+00');
INSERT INTO articles (article_id, company_id, title, body, category_id, author_id, reviewed_by, status, view_count, helpful_count, not_helpful_count, published_at, created_at, updated_at) VALUES (7, 1, 'Email archiving and retention policy', 'Overview of Northstar Holdings email archiving rules, retention periods and how to access the email archive. Emails older than 90 days are automatically archived but remain searchable in Outlook.', 1, 15, 2, 'PUBLISHED', 72, 22, 2, '2026-05-01 08:00:00+00', '2026-04-28 08:00:00+00', '2026-05-01 08:00:00+00');
INSERT INTO articles (article_id, company_id, title, body, category_id, author_id, reviewed_by, status, view_count, helpful_count, not_helpful_count, published_at, created_at, updated_at) VALUES (8, 1, 'How to submit an incident', 'Step-by-step guide to raising an IT incident through the ESM Hub portal. Navigate to Incidents > New Incident, describe the issue, select the affected service and assign a priority.', 5, 12, 4, 'PUBLISHED', 89, 28, 4, '2026-05-15 08:00:00+00', '2026-05-12 08:00:00+00', '2026-05-15 08:00:00+00');
INSERT INTO articles (article_id, company_id, title, body, category_id, author_id, reviewed_by, status, view_count, helpful_count, not_helpful_count, published_at, created_at, updated_at) VALUES (9, 1, 'Remote desktop access guide', 'Instructions for accessing your work desktop remotely using the Northstar RDS gateway. Requires VPN connection first. Launch Remote Desktop Connection and enter the host name provided by IT.', 6, 13, NULL, 'UNDER_REVIEW', 0, 0, 0, NULL, '2026-09-01 08:00:00+00', '2026-09-10 08:00:00+00');
INSERT INTO articles (article_id, company_id, title, body, category_id, author_id, reviewed_by, status, view_count, helpful_count, not_helpful_count, published_at, created_at, updated_at) VALUES (10, 1, 'Mobile device management (MDM) enrolment', 'How to enrol your company mobile device in the MDM system. Download the company portal app from the App Store or Google Play, sign in with your Northstar account and follow the enrolment wizard.', 2, 14, NULL, 'DRAFT', 0, 0, 0, NULL, '2026-10-01 08:00:00+00', '2026-10-05 08:00:00+00');
INSERT INTO articles (article_id, company_id, title, body, category_id, author_id, reviewed_by, status, view_count, helpful_count, not_helpful_count, published_at, created_at, updated_at) VALUES (11, 1, 'Finance system end-of-month close checklist', 'Checklist for finance teams during the monthly close process, including reconciliation steps, approval workflows and submission deadlines. Coordinate with your Finance Manager before starting.', 4, 15, 2, 'PUBLISHED', 44, 18, 1, '2026-06-01 08:00:00+00', '2026-05-28 08:00:00+00', '2026-06-01 08:00:00+00');
